export const SLOTS: Slot[] = ["look", "peluca", "zapatos", "acc"];
export const SLOT_NAMES: Record<Slot, string> = { look: "Look", peluca: "Peluca", zapatos: "Tacones", acc: "Toque final" };
export const PRICE: Record<Slot, number[]> = { look: [0, 60, 110, 180, 280, 420], peluca: [0, 30, 55, 90, 140, 210], acc: [0, 20, 35, 60, 90, 140], zapatos: [0, 25, 45, 75, 115, 170] };
export const TAG_OF_STYLE: Record<string, string> = { glam: "Glamour", clasico: "Glamour", retro: "Camp", street: "Edgy", futur: "Futurista", folk: "Folclórico", natural: "Folclórico" };
const normTxt = (x: unknown) => String(x || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
export const statOf = (id: string): [number, number] => ARMARIO_STATS[id] || [2, 3];
export function slotOf(id: string): Slot | null {
  for (const k of SLOTS) if ((ARMARIO[k] || []).some((x) => x.id === id)) return k;
  return null;
}
export const prendaById = (id: string) => SLOTS.map((k) => (ARMARIO[k] || []).find((x) => x.id === id)).find(Boolean) || null;
export const priceOf = (it: Prenda) => PRICE[slotOf(it.id) || "acc"][statOf(it.id)[0]];
export const prendaImg = (id: string) => `images/armario/${id}.webp`;

/** Cuánto encaja una prenda con la temática (0 a 1): misma regla que el probador del modo historia. */
export function fitScore(k: Slot, it: Prenda, cat: string): number {
  const TH = TEMAS_PASARELA.find((t) => t.n === cat) || null;
  const main = TH ? TH.tag : "Glamour";
  const style = TAG_OF_STYLE[it.s] === main;
  if (!TH) return !it.rv && (it.t || []).includes(cat) ? 1 : !it.rv && style ? 0.6 : 0.15;
  if (k === "look" && TH.rv) return it.rv ? 1 : 0.05;
  if (k === "look" && it.rv) return 0.2;
  let sc = 0;
  const th = Array.isArray(it.th) ? it.th : it.th ? [it.th] : [];
  if (th.some((x) => (TH.from || []).includes(x) || x === TH.id)) sc = 1;
  if ((it.t || []).some((x) => (TH.t || []).includes(x))) sc = Math.max(sc, 0.8);
  const txt = normTxt(`${it.n} ${it.desc || ""}`);
  const hits = (TH.kw || []).filter((w) => txt.includes(normTxt(w))).length;
  if (hits) sc = Math.max(sc, Math.min(1, 0.6 + 0.2 * hits));
  if (style) sc = Math.max(sc, 0.45);
  return sc || 0.1;
}
export type Outfit = Partial<Record<Slot, string>>;
/** Nota del estilismo (0 a 100): lo que encaja cada pieza (el look pesa el doble) y su impacto. Sin pieza, un básico prestado. */
export function outfitScore(o: Outfit, cat: string): number {
  const W: Record<Slot, number> = { look: 2, peluca: 1, zapatos: 0.6, acc: 0.8 };
  let sum = 0, w = 0;
  for (const k of SLOTS) {
    const it = o[k] ? prendaById(o[k]!) : null;
    const f = it ? fitScore(k, it, cat) : 0.3;
    const imp = it ? statOf(it.id)[0] : 1;
    sum += (f * 85 + imp * 3) * W[k];
    w += W[k];
  }
  return Math.round(Math.min(100, sum / w));
}
/** Las prendas que más encajan con la temática (para la tienda), de cada hueco. */
export function bestFor(k: Slot, cat: string, n = 6): Prenda[] {
  return (ARMARIO[k] || []).filter((x) => k !== "look" || !x.rv).map((x) => [fitScore(k, x, cat), x] as const).sort((a, b) => b[0] - a[0] || priceOf(a[1]) - priceOf(b[1])).slice(0, n).map((x) => x[1]);
}
